CREATE TABLE meme_evidence_versions(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES meme_campaigns(id),parent_id TEXT REFERENCES meme_evidence_versions(id),correction_id TEXT REFERENCES meme_source_corrections(id),effective_from INTEGER NOT NULL,through_at INTEGER NOT NULL,scope_wallets TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('observed','simulated')),state TEXT NOT NULL CHECK(state IN('building','checking','ready')),manifest_hash TEXT,created_at INTEGER NOT NULL);
CREATE TABLE meme_version_checks(version_id TEXT PRIMARY KEY REFERENCES meme_evidence_versions(id),wallet_index INTEGER NOT NULL,signature TEXT NOT NULL,source_id TEXT,source_root TEXT NOT NULL,base_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('checking','review_ready')));
CREATE INDEX meme_evidence_cutoff ON meme_evidence_versions(campaign_id,state,effective_from DESC);
CREATE TABLE meme_version_events(version_id TEXT NOT NULL REFERENCES meme_evidence_versions(id),event_key TEXT NOT NULL,payload TEXT NOT NULL,payload_hash TEXT NOT NULL,signature TEXT NOT NULL,event_index INTEGER NOT NULL,slot INTEGER NOT NULL,event_at INTEGER NOT NULL,PRIMARY KEY(version_id,event_key));
CREATE TABLE meme_version_wallets(version_id TEXT NOT NULL,event_key TEXT NOT NULL,wallet TEXT NOT NULL,signature TEXT NOT NULL,PRIMARY KEY(version_id,event_key,wallet),UNIQUE(version_id,signature,wallet),FOREIGN KEY(version_id,event_key) REFERENCES meme_version_events(version_id,event_key));
CREATE INDEX meme_version_scope ON meme_version_wallets(version_id,wallet,event_key);
CREATE TRIGGER meme_version_event_immutable BEFORE UPDATE ON meme_version_events BEGIN SELECT RAISE(ABORT,'Version events are immutable'); END;
CREATE TRIGGER meme_version_event_no_delete BEFORE DELETE ON meme_version_events BEGIN SELECT RAISE(ABORT,'Version events are immutable'); END;
CREATE TRIGGER meme_version_closed BEFORE INSERT ON meme_version_events WHEN (SELECT state FROM meme_evidence_versions WHERE id=NEW.version_id)!='building' BEGIN SELECT RAISE(ABORT,'Version is sealed'); END;
CREATE TRIGGER meme_version_manifest_immutable BEFORE UPDATE ON meme_evidence_versions WHEN OLD.state='ready' OR NEW.campaign_id!=OLD.campaign_id OR NEW.parent_id IS NOT OLD.parent_id OR NEW.correction_id IS NOT OLD.correction_id OR NEW.effective_from!=OLD.effective_from OR NEW.through_at!=OLD.through_at OR NEW.scope_wallets!=OLD.scope_wallets OR NEW.mode!=OLD.mode BEGIN SELECT RAISE(ABORT,'Version manifest is immutable'); END;
CREATE TRIGGER meme_version_frozen_history BEFORE INSERT ON meme_evidence_versions WHEN EXISTS(SELECT 1 FROM meme_settlements WHERE cutoff>=NEW.effective_from) BEGIN SELECT RAISE(ABORT,'Version cannot change frozen settlement history'); END;
CREATE TRIGGER meme_version_activate_frozen BEFORE UPDATE ON meme_evidence_versions WHEN NEW.state='ready' AND OLD.state!='ready' AND EXISTS(SELECT 1 FROM meme_settlements WHERE cutoff>=NEW.effective_from) BEGIN SELECT RAISE(ABORT,'Version cannot change frozen settlement history'); END;
CREATE UNIQUE INDEX meme_version_one_cutoff ON meme_evidence_versions(campaign_id,effective_from) WHERE state='ready';
CREATE TRIGGER meme_feed_immutable BEFORE UPDATE ON meme_price_feeds BEGIN SELECT RAISE(ABORT,'Approved feed mapping is immutable'); END;
CREATE TRIGGER meme_version_no_delete BEFORE DELETE ON meme_evidence_versions BEGIN SELECT RAISE(ABORT,'Evidence versions are immutable'); END;
CREATE TRIGGER meme_version_wallet_immutable BEFORE UPDATE ON meme_version_wallets BEGIN SELECT RAISE(ABORT,'Version wallet indexes are immutable'); END;
CREATE TRIGGER meme_version_wallet_no_delete BEFORE DELETE ON meme_version_wallets BEGIN SELECT RAISE(ABORT,'Version wallet indexes are immutable'); END;
CREATE TRIGGER meme_source_run_no_delete BEFORE DELETE ON meme_source_runs BEGIN SELECT RAISE(ABORT,'Source runs are immutable'); END;
CREATE TRIGGER meme_correction_manifest_immutable BEFORE UPDATE ON meme_source_corrections WHEN OLD.state!='proposed' OR NEW.id!=OLD.id OR NEW.parent_id IS NOT OLD.parent_id OR NEW.campaign_id!=OLD.campaign_id OR NEW.effective_from!=OLD.effective_from OR NEW.reason!=OLD.reason OR NEW.actor!=OLD.actor OR NEW.created_at!=OLD.created_at BEGIN SELECT RAISE(ABORT,'Correction provenance is immutable'); END;
CREATE TRIGGER meme_correction_no_delete BEFORE DELETE ON meme_source_corrections BEGIN SELECT RAISE(ABORT,'Correction provenance is immutable'); END;
